    return abs((7 / 4 - 2 * c2) * abs(2 * c2 + 1) - math.cos(x) * (math.cos(x) - math.cos(5 * x)))

def in_submitted(x):
    # Submitted family: x = ±pi/6 + k*pi  <=>  x mod pi in {pi/6, 5pi/6}
    r = x % math.pi
    return min(abs(r - math.pi / 6), abs(r - 5 * math.pi / 6)) < 1e-9

print("\nCOMPLETE SOLUTION SET (c = cos2x roots, exact enumeration):")
all_residuals_ok = True
missing = []
for name, val, ex in sorted(uniq, key=lambda t: t[1]):
    x0 = math.acos(max(-1.0, min(1.0, val))) / 2  # representative
    res = residual(x0)
    if res > 1e-9:
        all_residuals_ok = False
    tag = "exact" if ex else "quadratic surd"
    print(f"  c={val:+.12f} [{tag}, case {name}]  x = ±{x0/math.pi:.6f}*pi + k*pi"
          f"  residual={res:.2e}  {'OK' if res <= 1e-9 else 'BAD'}")
    if not (in_submitted(x0) and in_submitted(-x0)):
        missing.append((val, x0))

# 5) Check the submitted answer directly.
print("\nSUBMITTED ANSWER CHECK:")
for xs, label in [(math.pi / 6, "x = pi/6"), (-math.pi / 6, "x = -pi/6"),
                  (math.pi / 3, "x = pi/3 (not in submitted set)")]:
    print(f"  {label}: residual = {residual(xs):.3e}, in submitted family = {in_submitted(xs)}")

