print("  submitted members are genuine solutions:", "PASS" if sub_valid else "FAIL")

# 6) Verdict.
print()
if missing:
    for val, x0 in missing:
        print(f"MISSING: c=cos2x={val:+.1f}, x = ±{x0/math.pi:.6f}*pi + k*pi satisfies the equation")
    print("CHECK FAIL: submitted answer omits x = ±pi/3 + k*pi (cos2x = -1/2); it is incomplete.")
elif all_residuals_ok and sub_valid:
    print("CHECK PASS")
else:
