    tsub = SUBMITTED.split()

    status_in, stack_in, idx_in = scan(tin)
    if status_in is not True:
        print("UNSUPPORTED: input prefix is already invalid at index", idx_in)
        return

    # Forced completion: the open brackets left on the stack must be closed in LIFO order.
    expected_suffix = [OPENER_TO_CLOSER[o] for o in reversed(stack_in)]
    print("input open stack (bottom->top):", " ".join(stack_in))
    print("expected suffix:", " ".join(expected_suffix))

    # Submitted answer must preserve the prefix exactly.
    if tsub[:len(tin)] != tin:
