    cS = [cls_list[i] for i in S]
    cT = [cls_list[j] for j in T]
    if len(S) == 1 and len(T) == 1:
        return cS[0] == cT[0]
    if len(S) == 1 and len(T) == 2:
        return (cS[0] == 1 and cT == [2, 2]) or (cS[0] == 2 and cT == [3, 3])
    if len(S) == 2 and len(T) == 1:
        return (cT[0] == 1 and cS == [2, 2]) or (cT[0] == 2 and cS == [3, 3])
    return False


def successors(state):
