def complete_brackets(seq):
    pairs = {'(': ')', '[': ']', '{': '}'}
    closers = set(pairs.values())
    stack = []
    for ch in seq:
        if ch in pairs:
            stack.append(ch)
        elif ch in closers:
            if not stack or pairs[stack[-1]] != ch:
                return None, "mismatched closer " + ch
            stack.pop()
    completion = ''.join(pairs[c] for c in reversed(stack))
    return completion, None

