    "A": ["Britain", "Germany", "South Korea", "France"],
    "B": ["France", "Britain", "Germany", "South Korea"],
    "C": ["Germany", "Britain", "France", "South Korea"],
    "D": ["Germany", "Britain", "South Korea", "France"],
}
# Languages each person speaks: K=Korean, F=French, E=English, G=German
LANG = {
    "K": {"K"},
    "F": {"F", "G"},
    "B": {"E", "K"},
    "G": {"K", "F", "E", "G"},
}
ALL_FOUR = {"K", "F", "E", "G"}


def can_talk(a, b):
    return bool(LANG[a] & LANG[b])


solutions = []
for perm in itertools.permutations(PEOPLE):
    pos = {p: i + 1 for i, p in enumerate(perm)}

    def neighbors(p):
        return [q for q in PEOPLE if q != p and abs(pos[p] - pos[q]) == 1]

    # Korean: room larger than German's; speaks no foreign language;
    # cannot communicate with any neighbor.
    c_korean = (
        pos["K"] > pos["G"]
        and LANG["K"] == {"K"}
        and not any(can_talk("K", q) for q in neighbors("K"))
    )
    # French: can speak German; cannot communicate with any neighbor.
    c_french = "G" in LANG["F"] and not any(can_talk("F", q) for q in neighbors("F"))
    # British: can speak Korean; can communicate with exactly one neighbor.
    c_british = "K" in LANG["B"] and sum(can_talk("B", q) for q in neighbors("B")) == 1
    # German: speaks all four languages.
    c_german = ALL_FOUR <= LANG["G"]

    if c_korean and c_french and c_british and c_german:
        order = sorted(PEOPLE, key=lambda p: pos[p])
        solutions.append([NAME[p] for p in order])

matches = [k for k, v in OPTIONS.items() if any(v == s for s in solutions)]

if len(solutions) == 1 and len(matches) == 1:
    result = {
        "final_answer": matches[0],
        "evidence": {
            "solutions_found": len(solutions),
            "order_by_room": solutions[0],
        },
    }
else:
    result = {"final_answer": "UNSUPPORTED", "evidence": {"solutions_found": len(solutions)}}

print(json.dumps(result, separators=(",", ":")))
