    drawn = [(nodes[a], nodes[b]) for a, b in edges]
    return nodes, adj, drawn


def enumerate_cycles(adj, n_nodes):
    cycles, seen = [], set()

    def dfs(s, cur, path, vis):
        for nb in adj[cur]:
            if nb == s and len(path) >= 3:
                key = frozenset(
                    frozenset((path[k], path[(k + 1) % len(path)])) for k in range(len(path))
                )
                if key not in seen:
                    seen.add(key)
                    cycles.append(list(path))
            elif nb > s and nb not in vis and len(path) < MAXN:
                dfs(s, nb, path + [nb], vis | {nb})

    for s in range(n_nodes):
        dfs(s, s, [s], {s})
    return cycles


def reduce_cycle(P):
    P = list(P)
    changed = True
    while changed and len(P) > 3:
        changed = False
        n = len(P)
        for k in range(n):
            a, b, c = P[k - 1], P[k], P[(k + 1) % n]
            u, v = sub(a, b), sub(c, b)
            if abs(cross(u, v)) <= SIN_TOL * norm(u) * norm(v) and dot(u, v) < 0:
                del P[k]
                changed = True
                break
    return P


def area2(P):
    n = len(P)
    return sum(cross(P[k], P[(k + 1) % n]) for k in range(n))


def interior_angles(P):
    n = len(P)
    s = 1 if area2(P) > 0 else -1
    res = []
    for k in range(n):
        e_prev = sub(P[k], P[k - 1])
        e_cur = sub(P[(k + 1) % n], P[k])
        turn = math.degrees(math.atan2(cross(e_prev, e_cur), dot(e_prev, e_cur)))
        res.append(180 - s * turn)
    return res


def proper_cross(p1, p2, p3, p4):
    d1 = cross(sub(p2, p1), sub(p3, p1))
    d2 = cross(sub(p2, p1), sub(p4, p1))
    d3 = cross(sub(p4, p3), sub(p1, p3))
    d4 = cross(sub(p4, p3), sub(p2, p3))
    return d1 * d2 < 0 and d3 * d4 < 0


def is_simple(P):
    n = len(P)
    for i in range(n):
        for j in range(i + 1, n):
            if j == i + 1 or (i == 0 and j == n - 1):
                continue
            if proper_cross(P[i], P[(i + 1) % n], P[j], P[(j + 1) % n]):
                return False
    return True


def segment_covered(p, q, drawn):
    d = sub(q, p)
    L = norm(d)
    ivs = []
    for a, b in drawn:
        if abs(cross(sub(a, p), d)) / L > 1e-3 or abs(cross(sub(b, p), d)) / L > 1e-3:
            continue
        ta = dot(sub(a, p), d) / (L * L)
        tb = dot(sub(b, p), d) / (L * L)
        lo, hi = max(0.0, min(ta, tb)), min(1.0, max(ta, tb))
        if hi > lo:
            ivs.append((lo, hi))
    ivs.sort()
    cur = 0.0
    for lo, hi in ivs:
        if lo > cur + 1e-3:
            break
        cur = max(cur, hi)
    return cur >= 1 - 1e-3


def has_drawn_diagonal(P, drawn):
    n = len(P)
    for i in range(n):
        for j in range(i + 2, n):
            if i == 0 and j == n - 1:
                continue
            if segment_covered(P[i], P[j], drawn):
                return True
    return False


def eq_len(x, y):
    return abs(x - y) <= REL_LEN * max(x, y, 1e-12)


def classify(P):
    n = len(P)
    ang = interior_angles(P)
    sides = [norm(sub(P[(k + 1) % n], P[k])) for k in range(n)]
    convex = all(a < 180 - 1e-6 for a in ang)
    if n == 3:
        right = any(abs(a - 90) < ANG_TOL for a in ang)
        return "4" if right else "3"
    if n == 4:
        e = [sub(P[(k + 1) % 4], P[k]) for k in range(4)]
        npar = 0
        for i, j in ((0, 2), (1, 3)):
            if abs(cross(e[i], e[j])) / (norm(e[i]) * norm(e[j])) < SIN_TOL:
                npar += 1
        rect = all(abs(a - 90) < ANG_TOL for a in ang)
        if npar == 2:
            if rect:
                return "2" if all(eq_len(sides[0], s) for s in sides) else "1"
            return "5"
        if npar == 1:
            return "6"
        return None
    if n == 5:
        if not convex:
            return "8"
        if all(eq_len(sides[0], s) for s in sides) and all(abs(a - ang[0]) < ANG_TOL for a in ang):
            return "9"
        return "7"
    if n == 6:
        if all(eq_len(sides[0], s) for s in sides) and all(abs(a - 120) < ANG_TOL for a in ang):
            return "10"
        return None
    return None


def main():
    segs = parse_path(PATH)
    nodes, adj, drawn = build_graph(segs)
    cycles = enumerate_cycles(adj, len(nodes))

    found = {}
    polygons = []
    for cyc in cycles:
        P = reduce_cycle([nodes[k] for k in cyc])
        if len(P) < 3 or not is_simple(P):
            continue
        label = classify(P)
        if label is None:
            continue
        diag = has_drawn_diagonal(P, drawn)
        ok = label in ("3", "4") or not diag
        rec = {
            "label": label,
            "vertices": [[round(x, 3), round(y, 3)] for x, y in P],
            "drawn_diagonal": diag,
            "counted": ok,
        }
        polygons.append(rec)
        if ok:
            found.setdefault(label, 0)
            found[label] += 1

    found_set = set(found.keys())
    matches = [k for k, v in OPTIONS.items() if v == found_set]
    final = matches[0] if len(matches) == 1 else "UNSUPPORTED"

    print(json.dumps({
        "final_answer": final,
        "evidence": {
            "segments": len(segs),
            "graph_nodes": len(nodes),
            "cycles_examined": len(cycles),
            "qualifying_shape_ids": sorted(found_set),
            "polygons": polygons,
        },
    }, sort_keys=True))


if __name__ == "__main__":
    main()
```

