TOL = 2e-3       # coincidence / collinearity tolerance (coords are 5 dp)
ANG_TOL = 1e-3   # |sin| / |cos| tolerance for parallel and right-angle tests
LEN_TOL = 5e-3   # equal-length tolerance
DEG_TOL = 0.2    # regular-polygon angle tolerance in degrees

OPTIONS = {
    "A": {1}, "B": {5, 3}, "C": {4, 3}, "D": {4}, "E": {5, 10}, "F": {1, 3, 7},
    "G": {5}, "H": {4, 5, 6}, "I": {4, 5}, "J": {4, 2, 3}, "K": {4, 3, 10},
    "L": {4, 5, 1}, "M": {3, 6}, "N": {9}, "O": {4, 1}, "P": {5, 7},
}
SELECTED = "I"


def dist(p, q):
    return math.hypot(p[0] - q[0], p[1] - q[1])


def cross(ax, ay, bx, by):
    return ax * by - ay * bx


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def norm(v):
    return math.hypot(v[0], v[1])


def seg_hit(p, q, r, s):
    d1 = sub(q, p)
    d2 = sub(s, r)
    rp = sub(r, p)
    den = cross(d1[0], d1[1], d2[0], d2[1])
    if abs(den) < 1e-12:
        return None
    t = cross(rp[0], rp[1], d2[0], d2[1]) / den
    u = cross(rp[0], rp[1], d1[0], d1[1]) / den
    e = 1e-9
    if -e <= t <= 1 + e and -e <= u <= 1 + e:
        return (p[0] + t * d1[0], p[1] + t * d1[1])
    return None


def proj_dist(p, a, b):
    d = sub(b, a)
    L2 = d[0] ** 2 + d[1] ** 2
    t = ((p[0] - a[0]) * d[0] + (p[1] - a[1]) * d[1]) / L2
    t = min(1.0, max(0.0, t))
    qx, qy = a[0] + t * d[0], a[1] + t * d[1]
    return t, math.hypot(p[0] - qx, p[1] - qy)


def inside(pt, poly):
    x, y = pt
    c = False
    n = len(poly)
    for k in range(n):
        x1, y1 = poly[k]
        x2, y2 = poly[(k + 1) % n]
        if (y1 > y) != (y2 > y):
            xi = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
            if x < xi:
                c = not c
    return c


def bdist(pt, poly):
    n = len(poly)
    return min(proj_dist(pt, poly[k], poly[(k + 1) % n])[1] for k in range(n))


def angle_cos(a, b, c):
    u = sub(a, b)
    v = sub(c, b)
    return (u[0] * v[0] + u[1] * v[1]) / (norm(u) * norm(v))


def reduce_poly(P):
    P = list(P)
    changed = True
    while changed and len(P) > 3:
        changed = False
        n = len(P)
        for k in range(n):
            a, b, c = P[k - 1], P[k], P[(k + 1) % n]
            d = sub(c, a)
            L = norm(d)
            ba = sub(b, a)
            if L > 0 and abs(cross(ba[0], ba[1], d[0], d[1])) / L < TOL:
                del P[k]
                changed = True
                break
    return P


def classify(P):
    n = len(P)
    sides = [norm(sub(P[(k + 1) % n], P[k])) for k in range(n)]
    cr = []
    for k in range(n):
        e1 = sub(P[k], P[k - 1])
        e2 = sub(P[(k + 1) % n], P[k])
        cr.append(cross(e1[0], e1[1], e2[0], e2[1]))
    convex = all(c > 0 for c in cr)
    labs = set()
    info = {"n": n, "convex": convex, "sides": [round(s, 5) for s in sides]}

    def par(u, v):
        return abs(cross(u[0], u[1], v[0], v[1])) / (norm(u) * norm(v)) < ANG_TOL

    def regular():
        if not convex:
            return False
        m = sum(sides) / n
        if max(abs(s - m) for s in sides) > LEN_TOL:
            return False
        target = (n - 2) * 180.0 / n
        for k in range(n):
            c = angle_cos(P[k - 1], P[k], P[(k + 1) % n])
            ang = math.degrees(math.acos(max(-1.0, min(1.0, c))))
            if abs(ang - target) > DEG_TOL:
                return False
        return True

    if n == 3:
        mc = min(abs(angle_cos(P[(k - 1) % 3], P[k], P[(k + 1) % 3])) for k in range(3))
        info["min_abs_cos"] = mc
        labs.add(4 if mc < ANG_TOL else 3)
    elif n == 4:
        p1 = par(sub(P[1], P[0]), sub(P[2], P[3]))
        p2 = par(sub(P[2], P[1]), sub(P[3], P[0]))
        rc = abs(angle_cos(P[3], P[0], P[1]))
        info["pair_AB_CD_parallel"] = p1
        info["pair_BC_DA_parallel"] = p2
        info["abs_cos_corner0"] = rc
        if p1 and p2:
