print("arrangement vertices:", len(verts), " edges:", len(edges))

nb = {k: [] for k in range(len(verts))}
for k1, k2 in edges:
    nb[k1].append(k2)
    nb[k2].append(k1)
for k in nb:
    nb[k].sort(key=lambda w: math.atan2(verts[w][1] - verts[k][1],
                                        verts[w][0] - verts[k][0]))

# ---- half-edge face traversal ----
darts = []
for a, b in edges:
    darts.append((a, b))
    darts.append((b, a))
seen = set()
raw = []
for d0 in darts:
    if d0 in seen:
        continue
    cyc = []
    cur = d0
    while cur not in seen:
        seen.add(cur)
        a, b = cur
        cyc.append(a)
        nbrs = nb[b]
        i = nbrs.index(a)
        cur = (b, nbrs[(i - 1) % len(nbrs)])
    raw.append(cyc)


def area2(ids):
    s = 0.0
    n = len(ids)
    for k in range(n):
        x1, y1 = verts[ids[k]]
        x2, y2 = verts[ids[(k + 1) % n]]
        s += x1 * y2 - x2 * y1
    return s / 2.0


bounded = []
for cyc in raw:
    if area2(cyc) > 1e-9 and len(set(cyc)) == len(cyc):
        bounded.append(cyc)
print("half-edge cycles:", len(raw), " bounded simple faces:", len(bounded))

# ---- classify each bounded face, and verify it has no interior drawn line ----
all_labels = set()
all_chord_free = True
for idx, cyc in enumerate(bounded, 1):
    P = reduce_poly([verts[k] for k in cyc])
    chords = 0
    for k1, k2 in edges:
        a, b = verts[k1], verts[k2]
        for f in (0.25, 0.5, 0.75):
            pt = (a[0] + f * (b[0] - a[0]), a[1] + f * (b[1] - a[1]))
            if bdist(pt, P) > TOL and inside(pt, P):
                chords += 1
                break
    if chords:
        all_chord_free = False
    labs, info = classify(P)
    all_labels |= labs
    coords = ["(%.5f, %.5f)" % p for p in P]
    print("face %d: vertices=%s" % (idx, " ".join(coords)))
    print("   info=%s chords_inside=%d labels=%s" % (info, chords, sorted(labs)))

expected = OPTIONS[SELECTED]
matches = [k for k, v in OPTIONS.items() if v == all_labels]
print("derived shape labels:", sorted(all_labels))
print("selected option", SELECTED, "content:", sorted(expected))
print("options whose content equals derived labels:", matches)

if not bounded:
    print("CHECK UNKNOWN")
elif all_labels == expected and all_chord_free:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
