            ok = False
        magnitudes.append(abs(f(z)))
    increasing = all(magnitudes[i] < magnitudes[i + 1] for i in range(len(magnitudes) - 1))
    unbounded = magnitudes[-1] > Fraction(10 ** 6)
    ok = ok and increasing and unbounded
