        "M 10.2141,14.67885 L 10.2141,6.16512 M 10.2141,22.67885 L 10.2141,14.67885 M 10.2141,-0.0 L 5.10705,8.84567 "
        "M 18.2141,14.67885 L 18.2141,22.67885 M 10.2141,14.67885 L 18.2141,14.67885 M 0.0,8.80731 L 0.0,14.67885 "
        "M 18.2141,22.67885 L 10.2141,22.67885 M 0.0,0.0 L 0.0,8.80731 M 6.9282,18.67885 L 0.0,14.67885 "
        "M 0.0,22.67885 L 6.9282,18.67885 M 10.2141,14.67885 L 10.2141,21.07885")

OPTIONS = {"A": {2}, "B": {9}, "C": {8}, "D": {4}, "E": {2, 4, 6}, "F": set(), "G": {3},
           "H": {6, 8}, "I": {2, 8}, "J": {3, 4, 5}, "K": {3, 8, 10}, "L": {1, 2, 5, 10},
           "M": {1, 2, 8, 9}, "N": {2, 7}, "O": {2, 3, 6}, "P": {1, 2, 6, 10}}

def cross(o, a, b):
    return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def between(p, q, n):
    return (min(p[0], q[0]) <= n[0] <= max(p[0], q[0]) and
            min(p[1], q[1]) <= n[1] <= max(p[1], q[1]))

# 1. Parse exact segments
segs = []
for m in re.finditer(r"M\s*([-\d.]+),([-\d.]+)\s*L\s*([-\d.]+),([-\d.]+)", PATH):
    segs.append(((Fraction(m.group(1)), Fraction(m.group(2))),
                 (Fraction(m.group(3)), Fraction(m.group(4)))))

nodes = set()
for p, q in segs:
    nodes.add(p); nodes.add(q)

# 2. Split segments at collinear nodes -> planar edge set
edges = set()
for p, q in segs:
    on = [n for n in nodes if n not in (p, q) and cross(p, q, n) == 0 and between(p, q, n)]
    pts = sorted([p, q] + on, key=lambda t: (t[0]-p[0])**2 + (t[1]-p[1])**2)
    for a, b in zip(pts, pts[1:]):
        edges.add(frozenset((a, b)))

adj = {n: set() for n in nodes}
for e in edges:
    a, b = tuple(e)
    adj[a].add(b); adj[b].add(a)

# 3. Remove degree-2 collinear pass-through nodes
changed = True
while changed:
    changed = False
    for n in list(adj):
        if len(adj[n]) == 2:
            a, b = tuple(adj[n])
            if cross(a, n, b) == 0 and between(a, b, n):
                adj[a].discard(n); adj[b].discard(n)
                adj[a].add(b); adj[b].add(a)
                del adj[n]
                changed = True
                break

V = sorted(adj)
order = {v: i for i, v in enumerate(V)}
E2 = {frozenset((a, b)) for a in adj for b in adj[a]}

# 4. Enumerate simple cycles of length 3..10
def find_cycles(maxlen=10):
    res = set()
    def dfs(start, cur, path):
        for nb in adj[cur]:
            if nb == start and len(path) >= 3:
                cyc = tuple(path)
                k = min(range(len(cyc)), key=lambda i: order[cyc[i]])
                rot = cyc[k:] + cyc[:k]
                rev = (rot[0],) + tuple(reversed(rot[1:]))
                res.add(min(rot, rev, key=lambda c: [order[v] for v in c]))
            elif nb not in path and order[nb] > order[start] and len(path) < maxlen:
                dfs(start, nb, path + [nb])
    for s in V:
        dfs(s, s, [s])
    return res

def seg_hit(p1, p2, p3, p4):
    d1 = cross(p3, p4, p1); d2 = cross(p3, p4, p2)
    d3 = cross(p1, p2, p3); d4 = cross(p1, p2, p4)
    if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
        return True
    on = lambda p, q, r: cross(p, q, r) == 0 and between(p, q, r)
    return on(p3, p4, p1) or on(p3, p4, p2) or on(p1, p2, p3) or on(p1, p2, p4)

def ang_at(a, b, c):
    u = (a[0]-b[0], a[1]-b[1]); v = (c[0]-b[0], c[1]-b[1])
    lu = math.hypot(*u); lv = math.hypot(*v)
    d = (u[0]*v[0] + u[1]*v[1]) / (lu*lv)
    return math.degrees(math.acos(max(-1.0, min(1.0, d))))

def close(a, b, tol):
    return abs(a - b) <= tol

S_all = set()
evidence = []

for cyc in sorted(find_cycles(), key=len):
    n = len(cyc)
    simple = True
    for i in range(n):
        for j in range(i+1, n):
            if j == i+1 or (i == 0 and j == n-1):
