    if any(cross(cyc[i-1], cyc[i], cyc[(i+1) % n]) == 0 for i in range(n)):
        continue

    P = [(float(x), float(y)) for x, y in cyc]
    L = [math.dist(P[i], P[(i+1) % n]) for i in range(n)]
    area2 = sum(P[i][0]*P[(i+1) % n][1] - P[(i+1) % n][0]*P[i][1] for i in range(n))
    s = 1 if area2 > 0 else -1
    convex = all(
        (P[i][0]-P[i-1][0])*(P[(i+1) % n][1]-P[i][1]) - (P[i][1]-P[i-1][1])*(P[(i+1) % n][0]-P[i][0]) > 0
        if s > 0 else
        (P[i][0]-P[i-1][0])*(P[(i+1) % n][1]-P[i][1]) - (P[i][1]-P[i-1][1])*(P[(i+1) % n][0]-P[i][0]) < 0
        for i in range(n))
    ang = [ang_at(P[i-1], P[i], P[(i+1) % n]) for i in range(n)]

    def par(i, j):
        u = (P[(i+1) % n][0]-P[i][0], P[(i+1) % n][1]-P[i][1])
        w = (P[(j+1) % n][0]-P[j][0], P[(j+1) % n][1]-P[j][1])
        return abs(u[0]*w[1]-u[1]*w[0]) / (math.hypot(*u)*math.hypot(*w)) < 1e-3

    label = None
    if n == 3:
        right = any(close(a, 90, 0.05) for a in ang)
        label = "right triangle" if right else "triangle not right"
        S_all.add(4 if right else 3)
    elif n == 4:
        npar = int(par(0, 2)) + int(par(1, 3))
        rect = all(close(a, 90, 0.05) for a in ang)
        if rect:
            square = all(close(L[0], x, 1e-3) for x in L)
            label = "square" if square else "rectangle not square"
            S_all.add(2 if square else 1)
        elif npar == 2:
            label = "parallelogram not rectangle"; S_all.add(5)
        elif npar == 1:
            label = "trapezoid"; S_all.add(6)
    elif n == 5:
        eq_sides = all(close(L[0], x, 1e-3) for x in L)
        eq_angs = all(close(ang[0], a, 0.05) for a in ang)
        if convex and eq_sides and eq_angs:
            label = "regular pentagon"; S_all.add(9)
        elif convex:
            label = "irregular convex pentagon"; S_all.add(7)
        else:
            label = "irregular concave pentagon"; S_all.add(8)
    elif n == 6:
        if convex and all(close(L[0], x, 1e-3) for x in L) and all(close(a, 120, 0.05) for a in ang):
            label = "regular hexagon"; S_all.add(10)

    if label:
        evidence.append({"vertices": [[round(float(x), 4), round(float(y), 4)] for x, y in cyc],
                         "shape": label})

viewable = sorted(S_all)
matches = [k for k, v in OPTIONS.items() if k != "F" and v == S_all]
final_answer = matches[0] if matches else "F"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "viewable_shape_numbers": viewable,
        "accepted_polygons": evidence
    }
}))
