    return a[0] * b[1] - a[1] * b[0]


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def length(a):
    return math.hypot(a[0], a[1])


def close(a, b):
    return abs(a[0] - b[0]) < TOL and abs(a[1] - b[1]) < TOL


def seg_intersection(a, b, c, d):
    r, s = sub(b, a), sub(d, c)
    den = cross(r, s)
    if abs(den) < 1e-12:
        return None
    ca = sub(c, a)
    t = cross(ca, s) / den
    u = cross(ca, r) / den
    if -1e-9 <= t <= 1 + 1e-9 and -1e-9 <= u <= 1 + 1e-9:
        return (a[0] + t * r[0], a[1] + t * r[1])
    return None


def point_on_seg(p, a, b):
    r = sub(b, a)
    L = length(r)
    if L < TOL:
        return close(p, a)
    if abs(cross(sub(p, a), r)) / L > TOL:
        return False
    t = dot(sub(p, a), r) / (L * L)
    return -TOL / L <= t <= 1 + TOL / L


def inside(p, poly):
    n = len(poly)
    for i in range(n):
        if point_on_seg(p, poly[i], poly[(i + 1) % n]):
            return False  # boundary point, not strictly inside
    c = False
    for i in range(n):
        a, b = poly[i], poly[(i + 1) % n]
        if (a[1] > p[1]) != (b[1] > p[1]):
            x = a[0] + (p[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if p[0] < x:
