            path.append(nb)
            dfs(start, nb, path, visited)
            path.pop()
            visited.discard(nb)


for s in range(len(pts)):
    dfs(s, s, [s], {s})

print("simple cycles enumerated:", len(cycles))

# ---- analyse each cycle as a polygon ----
found_clean = set()
found_internal = set()

for key, path in cycles.items():
