    """True if segment pq is fully covered by drawn lines."""
    d = sub(q, p)
    L = dot(d, d)
    ivs = []
    for e in edges:
        u, v = tuple(e)
        if cross(d, sub(u, p)) == 0 and cross(d, sub(v, p)) == 0:
            tu = dot(sub(u, p), d) / L
            tv = dot(sub(v, p), d) / L
            lo = max(min(tu, tv), F(0))
            hi = min(max(tu, tv), F(1))
            if lo < hi:
                ivs.append((lo, hi))
    ivs.sort()
    cur = F(0)
    for lo, hi in ivs:
        if lo > cur:
            return False
        cur = max(cur, hi)
    return cur >= 1

