                   and all(s == sides2[0] for s in sides2)
                   and all(dot(E[i], E[(i + 1) % n]) == dot(E[0], E[1]) for i in range(n)))
        if n == 5:
            labels.add(9 if regular else (7 if convex else 8))
        elif regular:
