        if 0 < t < 1:
            px, py = ka[0] + t * dx, ka[1] + t * dy
            if math.hypot(px - n[0], py - n[1]) < 2e-4:
                inner.append((t, n))
    chain = [ka] + [n for _, n in sorted(inner)] + [kb]
    for u, v in zip(chain, chain[1:]):
        edges.add(frozenset((u, v)))

adj = {}
for e in edges:
    u, v = tuple(e)
    adj.setdefault(u, set()).add(v)
    adj.setdefault(v, set()).add(u)

# Neighbours sorted by angle (CCW) for half-edge face tracing.
order = {v: sorted(nb, key=lambda w, v=v: math.atan2(w[1] - v[1], w[0] - v[0]))
         for v, nb in adj.items()}

# Trace faces: at each arrival, take the clockwise-next edge. Interior faces get area > 0.
seen = set()
faces = []
for u in adj:
    for v in adj[u]:
        if (u, v) in seen:
            continue
        cyc = []
        a, b = u, v
        while (a, b) not in seen:
            seen.add((a, b))
            cyc.append(a)
            nb = order[b]
            c = nb[(nb.index(a) - 1) % len(nb)]
            a, b = b, c
        faces.append(cyc)


def signed_area(cyc):
    n = len(cyc)
    return sum(cyc[i][0] * cyc[(i + 1) % n][1] - cyc[(i + 1) % n][0] * cyc[i][1]
               for i in range(n)) / 2.0


inner_faces = [f for f in faces if signed_area(f) > 0]
outer_faces = [f for f in faces if signed_area(f) < 0]
print("faces traced:", len(faces), "outer:", len(outer_faces), "bounded:", len(inner_faces))


def corners(cyc):
    n = len(cyc)
    out = []
    for i in range(n):
        p, c, q = cyc[i - 1], cyc[i], cyc[(i + 1) % n]
        cr = (c[0] - p[0]) * (q[1] - c[1]) - (c[1] - p[1]) * (q[0] - c[0])
        denom = math.dist(p, c) * math.dist(c, q)
        if denom > 0 and abs(cr) / denom > EPS_SIN:
            out.append(c)
    return out


def classify(P):
    n = len(P)
    if n < 3:
        return set()

    def cross_at(i):
        p, c, q = P[i - 1], P[i], P[(i + 1) % n]
        return (c[0] - p[0]) * (q[1] - c[1]) - (c[1] - p[1]) * (q[0] - c[0])

    def dirv(i):
        return (P[(i + 1) % n][0] - P[i][0], P[(i + 1) % n][1] - P[i][1])

    def ang(i):
        p, c, q = P[i - 1], P[i], P[(i + 1) % n]
        a = (p[0] - c[0], p[1] - c[1])
        b = (q[0] - c[0], q[1] - c[1])
        cosv = (a[0] * b[0] + a[1] * b[1]) / (math.hypot(*a) * math.hypot(*b))
        t = math.degrees(math.acos(max(-1.0, min(1.0, cosv))))
        return t if cross_at(i) > 0 else 360.0 - t

    def parallel(i, j):
        di, dj = dirv(i), dirv(j)
        s = abs(di[0] * dj[1] - di[1] * dj[0]) / (math.hypot(*di) * math.hypot(*dj))
        return s < EPS_SIN

    sides = [math.dist(P[i], P[(i + 1) % n]) for i in range(n)]
    angs = [ang(i) for i in range(n)]
    convex = all(cross_at(i) > 0 for i in range(n))
    eq_sides = max(sides) - min(sides) < EPS_LEN
    eq_angs = max(angs) - min(angs) < EPS_ANG
    regular = eq_sides and eq_angs
    right_any = any(abs(a - 90) < EPS_ANG for a in angs)

    if n == 3:
        return {4} if right_any else {3}
    if n == 4:
        if all(abs(a - 90) < EPS_ANG for a in angs):
            print("    quad sides:", [round(s, 4) for s in sides])
            return {2} if eq_sides else {1}
        par = int(parallel(0, 2)) + int(parallel(1, 3))
        if par == 2:
            return {5}
        if par == 1:
            return {6}
        return set()
    if n == 5:
        if regular:
            return {9}
        return {7} if convex else {8}
    if n == 6 and regular:
        return {10}
    return set()


found = set()
for f in inner_faces:
    if len(set(f)) != len(f):
        print("bounded face revisits a node (contains internal spur or chord): skipped")
        continue
    P = corners(f)
    cats = classify(P)
    print(f"clean bounded face: corners={len(P)} area={signed_area(f):.4f} categories={sorted(cats)}")
    found |= cats

print("computed shape set:", sorted(found))
matches = [k for k, v in OPTIONS.items() if v == found]
print("options whose content equals computed set:", matches)
print("submitted", SUBMITTED, "content:", sorted(OPTIONS[SUBMITTED]))
print("CHECK PASS" if SUBMITTED in matches else "CHECK FAIL")
