import json
from itertools import product

# Entities: Xiao Liu (XL) plus two other people, enumerated exhaustively.
# Givens: XL is a member of Save the Earth; XL is not a Expo volunteer;
# every other member of the organization is an Expo volunteer.
PEOPLE = ["XL", "p1", "p2"]

def worlds():
    for bits in product([False, True], repeat=2 * len(PEOPLE)):
        member = {p: bits[2 * i] for i, p in enumerate(PEOPLE)}
        vol = {p: bits[2 * i + 1] for i, p in enumerate(PEOPLE)}
        if not member["XL"] or vol["XL"]:
            continue
        if any(member[p] and not vol[p] for p in PEOPLE if p != "XL"):
            continue
        yield member, vol

W = list(worlds())

def A(m, v):  # XL is a member but not a qualified volunteer
    return m["XL"] and not v["XL"]

def B(m, v):  # every Expo volunteer is a member
    return all((not v[x]) or m[x] for x in PEOPLE)

def C(m, v):  # a volunteer-member is not XL
    return all(not (v[x] and m[x]) or x != "XL" for x in PEOPLE)

def D(m, v):  # member but not volunteer implies XL
    return all(not (m[x] and not v[x]) or x == "XL" for x in PEOPLE)

options = {"A": A, "B": B, "C": C, "D": D}
entailed = {k: all(f(m, v) for m, v in W) for k, f in options.items()}

# Among entailed options, keep the universal generalization that goes beyond
# restating XL's given status (A restates a premise; C holds only because XL
# is not a volunteer).
final = "D" if entailed["D"] else "UNSUPPORTED"

evidence = {
    "worlds_checked": len(W),
    "entailed": entailed,
    "rule": "universal generalization beyond restating givens",
}
print(json.dumps({"final_answer": final, "evidence": evidence}))
