import itertools

# Exhaustive finite model check of the inference problem.
# Individual 0 is Xiao Liu. M = members of Save the Earth, W = Expo volunteers.
# Monadic sentences over 2 unary predicates plus 1 constant have a small-model
# property (4 type-classes plus the named individual), so domains of size 1..5
# cover every model type. This is an exhaustive check, not a sample.

MAX_N = 5

def subsets(n):
    for mask in range(1 << n):
        yield frozenset(i for i in range(n) if (mask >> i) & 1)

def base(n, M, W):
    # Xiao is a member and is not a qualified Expo volunteer.
    return (0 in M) and (0 not in W)

def premises_some(n, M, W):
    # Reading 1: some other member obtained the volunteer qualification.
    return base(n, M, W) and any((p != 0 and p in M and p in W) for p in range(n))

def premises_all(n, M, W):
    # Reading 2: every other member obtained the qualification, and at least one other member exists.
    return (base(n, M, W)
            and all((p in W) for p in M if p != 0)
            and any(p != 0 for p in M))

options = {
    "A": lambda n, M, W: (0 in M) and (0 not in W),
    "B": lambda n, M, W: all((p in M) for p in W),
    "C": lambda n, M, W: all((not (p in W and p in M)) or p != 0 for p in range(n)),
    "D": lambda n, M, W: all((p not in M) or (p in W) or p == 0 for p in range(n)),
}

def analyze(reading_name, premise):
    sat_count = 0
    counter = {k: None for k in options}
    for n in range(1, MAX_N + 1):
        for M in subsets(n):
            for W in subsets(n):
                if not premise(n, M, W):
                    continue
                sat_count += 1
                for k, f in options.items():
                    if counter[k] is None and not f(n, M, W):
                        counter[k] = (n, sorted(M), sorted(W))
    print(f"Reading: {reading_name}")
    print(f"  premise-satisfying models checked (n<=5): {sat_count}")
    entailed = {}
    for k in options:
        entailed[k] = counter[k] is None
        if counter[k] is None:
            print(f"  option {k}: ENTAILED (no countermodel)")
        else:
            n, M, W = counter[k]
            print(f"  option {k}: NOT entailed, countermodel n={n}, members={M}, volunteers={W}")
    return entailed

res_some = analyze("some other member qualified (faithful reading)", premises_some)
print()
res_all = analyze("every other member qualified (strong reading)", premises_all)
print()

# The submitted answer text matches option A:
# "Xiao Liu is a member of save the earth, but he has not been qualified as a volunteer."
print("Submitted claim corresponds to option A.")
print(f"A entailed under faithful reading: {res_some['A']}")
print(f"A entailed under strong reading:   {res_all['A']}")
print(f"B entailed under faithful reading: {res_some['B']} (expected False)")
print(f"D entailed under faithful reading: {res_some['D']} (expected False)")
print(f"C entailed under faithful reading: {res_some['C']} (holds because Xiao is never a volunteer)")

if res_some["A"] and res_all["A"]:
    print("CHECK PASS: submitted claim (option A) is entailed by the premises under both readings.")
else:
    print("CHECK FAIL: submitted claim (option A) is not entailed under at least one reading.")

if not res_some["B"] and not res_some["D"]:
    print("CHECK PASS: options B and D are refuted by countermodels under the faithful reading.")
else:
    print("CHECK FAIL: an option expected to be refuted is not refuted.")

print("NOTE: submitted text does not name a letter; verification is of the content it states.")
print("NOTE: C is also entailed (Xiao is never a volunteer), so A is the most direct inference, not the only true statement.")
