    "M 29.3405,-17.62663 L 34.99586,-14.98949 M 10.35209,0.0 L 10.35209,1.96 "
    "M 10.79637,5.0782 L 10.35209,0.0 M 7.55703,7.0 L 0.0,7.0 "
    "M 17.25429,-14.80182 L 18.29129,-17.02568"
