SUBMITTED = "E"
TOL = 1e-3        # merge / collinearity distance (coords rounded to 5 dp)
ANG_TOL = 1e-3    # radians; also sine tolerance for parallelism
REL_TOL = 1e-3    # relative length tolerance

OPTIONS = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5}, "E": {1, 5, 7, 8},
    "F": {1, 5, 7, 8, 4, 6}, "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2}, "N": {1, 8, 2, 4, 9},
    "O": {1, 5, 7, 8, 10}, "P": {1, 7, 8, 6},
}

SHAPE_NAMES = {
    1: "rectangle, not square, no diagonals",
    2: "square, no diagonals",
    3: "triangle, not right",
    4: "right triangle",
    5: "parallelogram, not rectangle, no diagonals",
    6: "trapezoid (exactly one parallel pair), no diagonals",
    7: "irregular convex pentagon, no diagonals",
    8: "irregular concave pentagon, no diagonals",
    9: "regular pentagon, no diagonals",
    10: "regular hexagon, no diagonals",
}


def parse_path(d):
    segs = []
    cur = None
    num = r"(-?\d+(?:\.\d*)?)"
    for cmd, xs, ys in re.findall(r"([ML])\s*" + num + r"\s*,\s*" + num, d):
        p = (float(xs), float(ys))
        if cmd == "M":
            cur = p
        else:
            if cur is not None:
                segs.append((cur, p))
            cur = p
    return segs


def build_nodes(segs):
    nodes = []

    def idx(p):
        for i, q in enumerate(nodes):
            if math.hypot(p[0] - q[0], p[1] - q[1]) < TOL:
                return i
        nodes.append(p)
        return len(nodes) - 1

    edges = set()
    for a, b in segs:
        ia, ib = idx(a), idx(b)
        if ia != ib:
            edges.add((min(ia, ib), max(ia, ib)))
    return nodes, edges


def on_interior(p, a, b):
    ax, ay = a
    bx, by = b
    px, py = p
    dx, dy = bx - ax, by - ay
    L2 = dx * dx + dy * dy
    t = ((px - ax) * dx + (py - ay) * dy) / L2
    if not (1e-9 < t < 1 - 1e-9):
        return None
    cx, cy = ax + t * dx, ay + t * dy
    if math.hypot(px - cx, py - cy) < TOL:
        return t
    return None


def split_edges(nodes, edges):
    changed = True
    while changed:
        changed = False
        for (a, b) in sorted(edges):
            hits = []
            for k in range(len(nodes)):
                if k == a or k == b:
                    continue
                t = on_interior(nodes[k], nodes[a], nodes[b])
                if t is not None:
                    hits.append((t, k))
            if hits:
                hits.sort()
                chain = [a] + [k for _, k in hits] + [b]
                edges.discard((a, b))
                for u, v in zip(chain, chain[1:]):
                    edges.add((min(u, v), max(u, v)))
                changed = True
                break
    return edges


def adjacency(nodes, edges):
    nb = {i: [] for i in range(len(nodes))}
    for a, b in edges:
        nb[a].append(b)
        nb[b].append(a)
    for v in nb:
        x0, y0 = nodes[v]
        nb[v].sort(key=lambda w: math.atan2(nodes[w][1] - y0, nodes[w][0] - x0))
    return nb


def trace_faces(nb):
    visited = set()
    faces = []
    for u in nb:
        for v in nb[u]:
            if (u, v) in visited:
                continue
            cyc = []
            a, b = u, v
            while (a, b) not in visited:
                visited.add((a, b))
                cyc.append(a)
                lst = nb[b]
                i = lst.index(a)
                c = lst[(i - 1) % len(lst)]
                a, b = b, c
            faces.append(cyc)
    return faces


def signed_area(P):
    s = 0.0
    n = len(P)
    for i in range(n):
        x1, y1 = P[i]
        x2, y2 = P[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return s / 2.0


def vec(a, b):
    return (b[0] - a[0], b[1] - a[1])


def cross(u, v):
    return u[0] * v[1] - u[1] * v[0]


def dot(u, v):
    return u[0] * v[0] + u[1] * v[1]


def norm(u):
    return math.hypot(u[0], u[1])


def dist_to_line(p, a, b):
    d = vec(a, b)
    return abs(cross(vec(a, p), d)) / norm(d)


def reduce_corners(P):
    P = list(P)
    changed = True
    while changed and len(P) > 3:
        changed = False
        n = len(P)
        for i in range(n):
            a, b, c = P[i - 1], P[i], P[(i + 1) % n]
            if dist_to_line(b, a, c) < TOL and dot(vec(a, b), vec(b, c)) > 0:
                del P[i]
                changed = True
                break
    return P


def classify(P):
    n = len(P)
    D = [vec(P[i], P[(i + 1) % n]) for i in range(n)]
    lens = [norm(d) for d in D]
    turns = []
    for i in range(n):
        d1, d2 = D[i - 1], D[i]
        turns.append(math.atan2(cross(d1, d2), dot(d1, d2)))
    convex = all(t > 0 for t in turns)           # polygon is CCW here
    inner = [math.pi - t for t in turns]

    def par(u, v):
        return abs(cross(u, v)) / (norm(u) * norm(v)) < ANG_TOL

    def right(a):
        return abs(a - math.pi / 2) < ANG_TOL

    def eq_len(xs):
        return max(xs) - min(xs) <= REL_TOL * max(xs)

    def all_equal_angles():
        return all(abs(a - inner[0]) < ANG_TOL for a in inner)

    labels = []
    if n == 3:
        labels = [4] if any(right(a) for a in inner) else [3]
    elif n == 4:
        npar = int(par(D[0], D[2])) + int(par(D[1], D[3]))
        if npar == 2:
            if all(right(a) for a in inner):
                labels = [2] if eq_len(lens) else [1]
            else:
                labels = [5]
        elif npar == 1:
            labels = [6]
    elif n == 5:
        if not convex:
            labels = [8]
        else:
            labels = [9] if (eq_len(lens) and all_equal_angles()) else [7]
    elif n == 6:
        if eq_len(lens) and all_equal_angles():
            labels = [10]
    info = {
        "corners": n,
        "convex": convex,
        "side_lengths": [round(x, 4) for x in lens],
        "interior_deg": [round(math.degrees(a), 3) for a in inner],
    }
    return labels, info


def main():
    print("method: exhaustive planar-arrangement face enumeration (no sampling)")
    segs = parse_path(SVG_PATH)
    print("segments parsed:", len(segs))

    nodes, edges = build_nodes(segs)
    edges = split_edges(nodes, edges)
    nb = adjacency(nodes, edges)
    print("planar nodes:", len(nodes), "undirected edges:", len(edges))

    faces = trace_faces(nb)
    bounded = 0
    viewable = set()
    for cyc in faces:
        P = [nodes[i] for i in cyc]
        A = signed_area(P)
        if A <= 0:
            continue  # outer (clockwise) boundary
        bounded += 1
        if len(set(cyc)) != len(cyc):
            print("face with dangling/internal edge skipped, area =", round(A, 5))
            continue
        C = reduce_corners(P)
        labels, info = classify(C)
        print("bounded face: area=%.4f corners=%s" % (A, [(round(x, 3), round(y, 3)) for x, y in C]))
        print("   info:", info)
        if labels:
            for l in labels:
                print("   -> item %d: %s" % (l, SHAPE_NAMES[l]))
                viewable.add(l)
        else:
            print("   -> matches none of items 1-10")

    print("clean bounded faces (arrangement cells):", bounded)
    print("viewable item set:", sorted(viewable))

    matches = [k for k, v in OPTIONS.items() if v == viewable]
    print("options whose content equals viewable set:", matches)

    if SUBMITTED in matches:
        print("submitted", SUBMITTED, "content:", sorted(OPTIONS[SUBMITTED]))
        print("CHECK PASS")
    elif matches:
        print("submitted", SUBMITTED, "content:", sorted(OPTIONS[SUBMITTED]))
        print("CHECK FAIL")
    else:
        print("UNSUPPORTED: computed shape set matches no listed option")
        print("CHECK UNKNOWN")


if __name__ == "__main__":
    main()
