from fractions import Fraction as F
import json

A = (2, 3, 0)
B = (0, 5, 4)
C = (4, 1, 8)
P = {'A': A, 'B': B, 'C': C}


def d2(p, q):
    return sum((x - y) ** 2 for x, y in zip(p, q))


pair_d2 = {
    ('A', 'B'): d2(P['A'], P['B']),
    ('B', 'C'): d2(P['B'], P['C']),
    ('A', 'C'): d2(P['A'], P['C']),
}

# Candidate squared edge lengths t2: every pairwise squared distance must be
# t2, 2*t2 or 3*t2 for a cube of edge^2 = t2.
cands = set()
for v in pair_d2.values():
    for k in (1, 2, 3):
        cands.add(F(v, k))

# Exhaustive search over (space-diagonal pair, third vertex) assignments.
solutions = []
for t2 in sorted(cands):
    if t2 <= 0:
        continue
    for X, Y, Z in [('A', 'C', 'B'), ('A', 'B', 'C'), ('B', 'C', 'A')]:
        dXY = d2(P[X], P[Y])
        dXZ = d2(P[X], P[Z])
        dYZ = d2(P[Y], P[Z])
        if dXY != 3 * t2:
            continue
        # A vertex off a space diagonal is adjacent to one endpoint (t2)
        # and face-diagonal to the other (2*t2).
        if sorted([F(dXZ), F(dYZ)]) != sorted([t2, 2 * t2]):
            continue
        center = tuple((F(P[X][i]) + F(P[Y][i])) / 2 for i in range(3))
        solutions.append({
            't2': str(t2),
            'diagonal': [X, Y],
            'third': Z,
            'center': [str(c) for c in center],
        })

distinct_centers = {tuple(s['center']) for s in solutions}

if len(distinct_centers) == 1:
    c = list(distinct_centers)[0]
    final_answer = "(" + ", ".join(c) + ")"
else:
