f = {4: F(1, 16), 3: -c, 2: F(1, 8), 1: F(0), 0: F(1)}

def deriv(p):
    return {e - 1: v * e for e, v in p.items() if e > 0 and v * e != 0}

def ev(p, x):
    return sum((v * x ** e for e, v in p.items()), F(0))

def divide_root(p, r):
    """Synthetic division of p by (x - r). Returns (remainder, quotient dict)."""
    deg = max(p)
    coeffs = [p.get(e, F(0)) for e in range(deg, -1, -1)]
    out = [coeffs[0]]
    for a in coeffs[1:]:
        out.append(a + out[-1] * r)
    rem = out[-1]
    quot_coeffs = out[:-1]
    qdeg = deg - 1
    quot = {qdeg - i: v for i, v in enumerate(quot_coeffs) if v != 0}
    return rem, quot

k = deriv(f)  # k(x) = f'(x)

# Enumerate candidate rational roots p/q
cands = set()
for p in range(-24, 25):
    for q in range(1, 13):
        cands.add(F(p, q))

roots = {}  # root -> multiplicity
work = dict(k)
for r in sorted(cands):
    if ev(k, r) != 0:
        continue
    m = 0
    while max(work, default=-1) >= 1:
        rem, quot = divide_root(work, r)
        if rem != 0:
            break
        work = quot
        m += 1
    if m > 0:
        roots[r] = m

# Remaining polynomial should be a nonzero constant (leading coefficient)
lead = work.get(0, F(0))
assert max(work) == 0 and lead != 0, "not fully factored over rationals"

# Independent check: rebuild product and compare coefficients exactly
def mul(p, q):
    out = {}
    for e1, v1 in p.items():
        for e2, v2 in q.items():
            out[e1 + e2] = out.get(e1 + e2, F(0)) + v1 * v2
    return {e: v for e, v in out.items() if v != 0}

rebuilt = {0: lead}
