    if r == 0:
        base = "s"
    elif r > 0:
        base = f"(s - {r})"
    else:
        base = f"(s + {-r})"
    return base if m == 1 else f"{base}**{m}"

parts = [str(lead)] + [fmt_root_factor(r, m) for r, m in sorted(roots.items())]
