    closer = {'(': ')', '[': ']', '{': '}'}
    completion = "".join(closer[c] for c in reversed(stack))
    return completion, "ok"

tokens = "{ [ [ ] [ ]".split()
completion, status = complete_brackets(tokens)

if completion is None:
    result = {"final_answer": "UNSUPPORTED", "evidence": {"status": status}}
else:
    result = {
        "final_answer": " ".join(completion),
        "evidence": {
            "input_tokens": len(tokens),
            "unclosed_after_input": [c for c in tokens if c in "([{"],
            "status": status,
            "completion_length": len(completion),
        },
    }

print(json.dumps(result, separators=(",", ":")))
