import json
import unicodedata

SCHWA = "\u0259"
LAB = "\u02b7"
MACRON = "\u0304"
VOWELS = set("aeiou")
SONOR = set("mnlwjy")
CONS_MAP = {"d": "t", "b": "p", "k": "g", "c": "j", "x": "q", "\u0263": "q"}

EXAMPLES = [
    ("tmi'gn", "[d\u0259m\u012bg\u0259n]"),
    ("an'stawteg", "[an\u0259stawtek]"),
    ("gjiansale'wit", "[\u0259kciansal\u0113wit]"),
    ("mgumie'jo'tlatl", "[\u0259mkumi\u0113j\u014dd\u0259l\u0259d\u0259l]"),
    ("amqwanji'j", "[amx\u02b7anc\u012bc]"),
    ("e'jnt", "[\u0113j\u0259nt]"),
    ("tplutaqan", "[\u0259tp\u0259ludа\u0263an]"),
    ("ge'gwising", "[g\u0113g\u02b7isink]"),
    ("lnu'sgw", "[l\u0259n\u016bskw]"),
    ("g'p'ta'q", "[g\u0259b\u0259d\u0101x]"),
    ("epsaqtejg", "[epsaxteck]"),
]


def segments(ipa):
    s = unicodedata.normalize("NFD", ipa)
    segs = []
    for ch in s:
        if ch in "[]":
            continue
        if ch == LAB and segs:
            segs[-1]["lab"] = True
        elif ch == MACRON and segs:
            segs[-1]["stress"] = True
        else:
            segs.append({"ph": ch, "lab": False, "stress": False})
    return segs


def transcribe(ipa):
    segs = segments(ipa)
    out = []
    for i, sg in enumerate(segs):
        ph = sg["ph"]
        if ph == SCHWA:
            # schwa written as apostrophe after a consonant when followed by an obstruent
            prev_cons = i > 0 and segs[i - 1]["ph"] not in VOWELS and segs[i - 1]["ph"] != SCHWA
            nxt = segs[i + 1]["ph"] if i + 1 < len(segs) else None
            if prev_cons and nxt is not None and nxt not in VOWELS and nxt not in SONOR:
                out.append("'")
            continue
        if sg["lab"]:
            out.append(CONS_MAP.get(ph, ph) + "w")
            continue
        base = CONS_MAP.get(ph, ph)
        out.append(base)
        if sg["stress"]:
            out.append("'")
    return "".join(out)


matches = 0
for orth, ipa in EXAMPLES:
    if transcribe(ipa) == orth:
        matches += 1

target = "[alapt\u0259k]"
final = transcribe(target) if matches == len(EXAMPLES) else "UNSUPPORTED"

print(json.dumps({
