        "rule_matches": f"{matches}/{len(EXAMPLES)}",
        "target_ipa": target,
        "rules": "d>t, b>p, k>g, c>j, x/gamma>q, xw>qw, kw>gw, macron vowel>V+', schwa>' after consonant before obstruent, else dropped"
    }
}, ensure_ascii=False))
