import math
import json

S, Q = 9.0, 14.0
ZMAX = (18.0 + math.sqrt(624.0)) / 6.0  # largest z admitting real x, y (discriminant >= 0)


def F(x, y, z):
    return sum((a * a + b * b) / (a + b) for a, b in ((x, y), (x, z), (y, z)))


def point(z):
    # x + y = S - z, xy = Q - z(S - z); need z > 0, x > 0, y > 0
    s = S - z
    p = Q - z * s
    if z <= 0 or s <= 0 or p <= 0:
        return None
    d = max(0.0, s * s - 4.0 * p)
    r = math.sqrt(d)
    x, y = (s + r) / 2.0, (s - r) / 2.0
    if x <= 0 or y <= 0:
        return None
    return (x, y, z)


N = 400000
best_v, best_q = None, None
grid_feasible = 0
for k in range(N + 1):
    z = ZMAX * k / N if k < N else ZMAX  # includes the endpoint exactly
    q = point(z)
    if q is None:
        continue
    grid_feasible += 1
    v = F(*q)
    if best_v is None or v < best_v:
        best_v, best_q = v, q

# Symmetric candidate x = y = t: 3t^2 - 18t + 14 = 0, z = 9 - 2t > 0
t = (18.0 - math.sqrt(156.0)) / 6.0
zs = 9.0 - 2.0 * t
sym_v = F(t, t, zs)
closed_v = (1557.0 - 39.0 * math.sqrt(39.0)) / 95.0

checks = {
    "sym_point_feasible": zs > 0 and abs(3 * t * t - 18 * t + 14) < 1e-12,
    "grid_min_matches_sym": abs(best_v - sym_v) < 1e-9 and best_v >= sym_v - 1e-9,
    "sym_matches_closed_form": abs(sym_v - closed_v) < 1e-9,
}

if all(checks.values()):
    final_answer = "(1557 - 39*sqrt(39))/95 ~ %.10f" % best_v
else:
    final_answer = "UNSUPPORTED"

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "min_value_numeric": round(best_v, 10),
        "argmin_xyz": [round(c, 8) for c in best_q],
        "sym_point_xyz": [round(t, 8), round(t, 8), round(zs, 8)],
        "grid_feasible_points": grid_feasible,
        "checks": checks,
    },
}))
