import json

N = 33146799


def is_prime(m):
    # Independent primality check: trial division by odd candidates up to sqrt(m).
    if m < 2:
        return False
    if m % 2 == 0:
        return m == 2
    d = 3
    while d * d <= m:
        if m % d == 0:
            return False
        d += 2
    return True


def factor_trial(n):
    # Trial division with 2 then odd candidates; records each prime with multiplicity.
    factors = []
    d = 2
    rem = n
    while d * d <= rem:
        while rem % d == 0:
            factors.append(d)
            rem //= d
        d += 1 if d == 2 else 2
    if rem > 1:
        factors.append(rem)
    return factors


def factor_by_enumeration(n):
    # Second method: exhaustive search over all candidates 2..n-independent bound check
    # using sqrt bound, counting multiplicities of every divisor that is prime.
    limit = int(n ** 0.5) + 1
    primes_found = []
    rem = n
    for c in range(2, limit + 1):
        if rem == 1:
            break
        if rem % c == 0 and is_prime(c):
            while rem % c == 0:
                primes_found.append(c)
                rem //= c
    if rem > 1:
        primes_found.append(rem)
    return primes_found


def exponent_form(factors):
    counts = {}
    for p in factors:
        counts[p] = counts.get(p, 0) + 1
    parts = []
    for p in sorted(counts):
        e = counts[p]
        parts.append(str(p) if e == 1 else f"{p}^{e}")
    return " * ".join(parts), counts


f1 = factor_trial(N)
f2 = factor_by_enumeration(N)

checks = {
    "method_agreement": f1 == f2,
    "product_matches": _prod_ok if (_prod_ok := (eval("*".join(map(str, f1))) == N)) else False,
    "all_prime": all(is_prime(p) for p in f1),
    "sorted_ascending": f1 == sorted(f1),
}

if all(checks.values()):
    expr, counts = exponent_form(f1)
    result = {
        "final_answer": expr,
        "evidence": {
            "n": N,
            "prime_factors_with_multiplicity": f1,
            "distinct_primes": sorted(counts),
            "exponents": {str(p): counts[p] for p in sorted(counts)},
            "checks": checks,
        },
    }
else:
    result = {
        "final_answer": "UNSUPPORTED",
        "evidence": {"n": N, "checks": checks},
    }

print(json.dumps(result, separators=(",", ":")))
