# Exact residuals of the three equations (each should be 0 at a solution).
def r1(x, y, z): return 12*x - 9*y*y - 7
def r2(x, y, z): return 6*y - 9*z*z + 2
def r3(x, y, z): return 12*z - 9*x*x - 4

def target(x, y, z):
    return 6*x*x + 9*y*y + 12*z*z

# Identity check: r1+r2+r3 + (3x-2)^2 + (3y-1)^2 + (3z-2)^2 == 0 for all x, y, z.
identity_ok = True
test_points = [Fraction(p, q) for p in range(-7, 8) for q in (1, 2, 3, 5)]
for i, a in enumerate(test_points):
    b = test_points[(i * 7 + 3) % len(test_points)]
    c = test_points[(i * 11 + 5) % len(test_points)]
    lhs = (r1(a, b, c) + r2(a, b, c) + r3(a, b, c)
           + (3*a - 2)**2 + (3*b - 1)**2 + (3*c - 2)**2)
    if lhs != 0:
        identity_ok = False
        break

def frac_sqrt(q):
    if q < 0:
        return None
    n, d = q.numerator, q.denominator
    rn, rd = isqrt(n), isqrt(d)
    if rn * rn == n and rd * rd == d:
        return Fraction(rn, rd)
    return None

# Finite exact search over rationals with small denominators in [-3, 3].
cands = sorted({Fraction(p, q) for q in range(1, 7) for p in range(-18, 19)
                if abs(Fraction(p, q)) <= 3})

solutions = set()
for x in cands:
    for y in cands:
        z2 = (6*y + 2) / 9          # from r2 = 0 with z^2 = (6y+2)/9
        r = frac_sqrt(z2)
        if r is None:
            continue
        for z in {r, -r}:
            if r1(x, y, z) == 0 and r3(x, y, z) == 0:
                solutions.add((x, y, z))

targets = {target(*s) for s in solutions}

if identity_ok and solutions and targets == {Fraction(9)}:
    result = {
        "final_answer": str(9),
        "evidence": {
            "identity_ok": identity_ok,
            "grid_solutions": sorted([[str(v) for v in s] for s in solutions]),
            "targets": [str(t) for t in sorted(targets)],
            "method": "sum of squares: (3x-2)^2+(3y-1)^2+(3z-2)^2 = -(r1+r2+r3)"
        }
    }
    print(json.dumps(result))
else:
    print(json.dumps({"final_answer": "UNSUPPORTED",
                      "evidence": {"identity_ok": identity_ok,
                                   "num_solutions": len(solutions)}}))
