from fractions import Fraction as F
import json

def f(x):
    return x**3 + x**2 - 2*x - 1

def bisect(a, b, fa):
    lo, hi, flo = a, b, fa
    for _ in range(60):
        mid = (lo + hi) / 2
        fm = f(mid)
        if fm == 0:
            return mid
        if (flo < 0) == (fm < 0):
            lo, flo = mid, fm
        else:
            hi = mid
    return (lo + hi) / 2

# Exhaustive exact-fraction grid scan over [-3, 3] with step 1/1000
xs = [F(k, 1000) for k in range(-3000, 3001)]
raw = []
for i in range(len(xs) - 1):
    a, b = xs[i], xs[i + 1]
    fa, fb = f(a), f(b)
    if fa == 0:
        raw.append(a)
    elif fa * fb < 0:
        raw.append(bisect(a, b, fa))
if f(xs[-1]) == 0:
    raw.append(xs[-1])

# Deduplicate roots
roots = []
for r in raw:
    rf = float(r)
    if all(abs(rf - float(s)) > 1e-9 for s in roots):
        roots.append(r)
roots.sort()

options = {
    "A": (F(-2), F(-1)),
    "B": (F(-1), F(0)),
    "C": (F(0), F(1)),
    "D": (F(1), F(2)),
}

counts = {}
for name, (a, b) in options.items():
    counts[name] = sum(1 for r in roots if a < r < b)

no_root = [name for name, c in counts.items() if c == 0]

if len(no_root) == 1:
    final_answer = no_root[0]
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "roots_approx": [round(float(r), 9) for r in roots],
    "root_count": len(roots),
    "roots_per_option": counts,
    "options_with_no_root": no_root,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
