    ("not_trades", "dalmatian", "stork"),
}
MONEY = {"stork": 98}  # no walrus entry: closed world, so Rule3 cannot fire
DOMAIN = ["ant", "stork", "dragon", "mannikin", "mouse", "worm", "crow", "dalmatian",
          "liger", "llama", "walrus", "beetle", "cobra", "dinosaur", "husky",
          "chihuahua", "fish", "goat", "wolf"]
# (preferred, inferior)
SUPERIOR = {("R3", "R1"), ("R5", "R2"), ("R6", "R8"), ("R7", "R4")}


def val(atom, T):
    if atom in T:
        return T[atom] is True
    return atom in FACTS  # closed world: absent atoms are false


def r1(T):
    if val(("negotiates_deal", "ant", "stork"), T) and val(("not_trades", "dalmatian", "stork"), T):
        return [(("builds_plant", "stork"), True)]
    return []


def r2(T):
    if any(val(("builds_plant", x), T) for x in DOMAIN):
        return [(("shouts_beetle", "mouse"), False)]
    return []


def r3(T):
    s, w = MONEY.get("stork"), MONEY.get("walrus")
    if s is not None and w is not None and s > w:
        return [(("builds_plant", "stork"), False)]
    return []


def r4(T):
    if val(("location", "mouse", "Africa"), T):
        return [(("smiles_cobra", "mouse"), True)]
    return []


