        return [(("smiles_cobra", "mouse"), False)]
    return []


def r8(T):
    if any(("acquires_photo", x, "fish") in FACTS for x in DOMAIN):
        return [(("call_husky", "llama"), False)]
    return []


RULES = [("R1", r1), ("R2", r2), ("R3", r3), ("R4", r4),
         ("R5", r5), ("R6", r6), ("R7", r7), ("R8", r8)]


def run():
    T, conflicts, fired = {}, [], []
    for _ in range(10):
        fired = [(name, atom, pol) for name, fn in RULES for atom, pol in fn(T)]
        newT = {}
        for name, atom, pol in fired:
