    try:
        results[key] = evaluate(translate(text))
    except Exception as e:  # cannot settle this expression
        errors.append(key)

true_keys = sorted(k for k, v in results.items() if v)

if not errors and len(true_keys) == 1:
    final = true_keys[0]
else:
    final = "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "values": {k: results.get(k) for k in sorted(EXPRS)},
        "true_count": len(true_keys),
        "errors": errors,
    },
}, separators=(",", ":")))
