import itertools
import json

def imp(a, b):
    return (not a) or b

# Propositional variables:
#   L: we realize the leap from developing to developed
#   C: we obtain a large amount of capital support
#   S: we have a high savings rate
models = list(itertools.product([False, True], repeat=3))  # (L, C, S)

# Premises: large capital is necessary for the leap (L -> C);
#           high savings is necessary for large capital (C -> S).
def premises(L, C, S):
    return imp(L, C) and imp(C, S)

options = {
    "A": lambda L, C, S: imp(C, L),        # capital -> leap
    "B": lambda L, C, S: imp(S, C),        # savings -> capital
    "C": lambda L, C, S: imp(not C, not S),  # no capital -> no high savings
    "D": lambda L, C, S: imp(not S, not L),  # no high savings -> no leap
}

satisfying = [m for m in models if premises(*m)]

entailed = []
witnesses = {}
for key, f in options.items():
    counter = [m for m in satisfying if not f(*m)]
    if counter:
        L, C, S = counter[0]
        witnesses[key] = {"L": L, "C": C, "S": S}
    else:
        entailed.append(key)

final_answer = entailed[0] if len(entailed) == 1 else "UNSUPPORTED"

evidence = {
    "variables": {"L": "leap", "C": "large capital", "S": "high savings"},
    "premise_models": len(satisfying),
    "entailed_options": entailed,
    "counterexample_witnesses": witnesses,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
