import itertools
import json

STUDENTS = ["Louis", "Mollie", "Onyx", "Ryan", "Tiffany", "Yoshio"]
YEARS = [1921, 1922, 1923, 1924]

def satisfies_rules(a):
    # a maps year -> student; each year has exactly one student, students distinct.
    year_of = {s: y for y, s in a.items()}
    # Only Louis or Tiffany can be assigned to 1923.
    if a[1923] not in ("Louis", "Tiffany"):
        return False
    # If Mollie is assigned, she must be in 1921 or 1922.
    if "Mollie" in year_of and year_of["Mollie"] not in (1921, 1922):
        return False
    # If Tiffany is assigned, Ryan must be assigned.
    if "Tiffany" in year_of and "Ryan" not in year_of:
        return False
    # If Ryan is assigned, Onyx must be assigned to the year immediately prior.
    if "Ryan" in year_of:
        if "Onyx" not in year_of:
            return False
        if year_of["Onyx"] != year_of["Ryan"] - 1:
            return False
    return True

# Antecedent of the question: both Ryan and Yoshio are assigned.
def antecedent(a):
    assigned = set(a.values())
    return "Ryan" in assigned and "Yoshio" in assigned

OPTIONS = {
    "A": lambda a: a[1923] == "Louis",
    "B": lambda a: a[1921] == "Mollie",
    "C": lambda a: a[1922] == "Onyx",
    "D": lambda a: a[1924] == "Tiffany",
    "E": lambda a: a[1922] == "Yoshio",
}

valid_count = 0
possible = {k: 0 for k in OPTIONS}

# Exhaustive enumeration of all injective assignments of 4 students to 4 years.
for perm in itertools.permutations(STUDENTS, len(YEARS)):
    a = dict(zip(YEARS, perm))
    if not antecedent(a):
        continue
    if not satisfies_rules(a):
        continue
    valid_count += 1
    for key, pred in OPTIONS.items():
        if pred(a):
            possible[key] += 1

could_be_true = [k for k, n in possible.items() if n > 0]

if len(could_be_true) == 1:
    final = could_be_true[0]
else:
    final = "UNSUPPORTED"

result = {
    "final_answer": final,
    "evidence": {
        "valid_assignments_with_Ryan_and_Yoshio": valid_count,
        "option_witness_counts": possible,
        "options_that_could_be_true": could_be_true,
    },
}
print(json.dumps(result, separators=(",", ":")))
