import json
from itertools import permutations

KOR, FRA, BRI, GER = "South Korea", "France", "Britain", "Germany"
NATS = [KOR, FRA, BRI, GER]

# Languages each person can speak, from the problem statements.
LANG = {
    KOR: {"Korean"},
    FRA: {"French", "German"},
    BRI: {"English", "Korean"},
    GER: {"German", "Korean", "French", "English"},
}
FOUR_LANGS = {"Korean", "French", "English", "German"}

OPTIONS = {
    "A": [BRI, GER, KOR, FRA],
    "B": [FRA, BRI, GER, KOR],
    "C": [GER, BRI, FRA, KOR],
    "D": [GER, BRI, KOR, FRA],
}

def can_talk(a, b):
    return bool(LANG[a] & LANG[b])

solutions = []
for order in permutations(NATS):
    # order[i] lives in room i+1 on the same side
    room = {n: i + 1 for i, n in enumerate(order)}

    def neighbors(n):
        return [m for m in NATS if abs(room[m] - room[n]) == 1]

    ok = True
    # Korean: room larger than German's; speaks no foreign language; no neighbor can talk to him
    ok &= room[KOR] > room[GER]
    ok &= LANG[KOR] == {"Korean"}
    ok &= not any(can_talk(KOR, m) for m in neighbors(KOR))
    # French: speaks German; no neighbor can talk to him
    ok &= "German" in LANG[FRA]
    ok &= not any(can_talk(FRA, m) for m in neighbors(FRA))
    # British: speaks Korean; can talk with exactly one neighbor
    ok &= "Korean" in LANG[BRI]
    ok &= sum(can_talk(BRI, m) for m in neighbors(BRI)) == 1
    # German: speaks the languages of all four countries
    ok &= FOUR_LANGS <= LANG[GER]

    if ok:
        solutions.append(list(order))

letter = "UNSUPPORTED"
matched = []
if len(solutions) == 1:
    for key, seq in OPTIONS.items():
        if seq == solutions[0]:
            letter = key
            matched.append(key)

result = {
    "final_answer": letter,
    "evidence": {
        "solution_count": len(solutions),
        "room_order_1_to_4": solutions[0] if len(solutions) == 1 else None,
        "matched_options": matched,
    },
}
print(json.dumps(result, separators=(",", ":")))
