LEN_TOL = 1e-3      # relative tolerance for length equality

OPTIONS = {
    "A": {1}, "B": {5, 3}, "C": {4, 3}, "D": {4}, "E": {5, 10}, "F": {1, 3, 7},
    "G": {5}, "H": {4, 5, 6}, "I": {4, 5}, "J": {4, 2, 3}, "K": {4, 3, 10},
    "L": {4, 5, 1}, "M": {3, 6}, "N": {9}, "O": {4, 1}, "P": {5, 7},
}


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def norm(a):
    return math.hypot(a[0], a[1])


def sin_between(u, v):
    return abs(cross(u, v)) / (norm(u) * norm(v))


def cos_between(u, v):
    return dot(u, v) / (norm(u) * norm(v))


def parse_segments(d):
    toks = re.findall(r"[MLZmlz]|[-+]?(?:\d+\.?\d*|\.\d+)", d)
    segs, cmd, cur, i = [], None, None, 0
    while i < len(toks):
        t = toks[i]
        if t.isalpha():
            cmd = t.upper()
            i += 1
            continue
        p = (float(t), float(toks[i + 1]))
        i += 2
        if cmd == "M":
            cur = p
        elif cmd == "L":
            segs.append((cur, p))
            cur = p
    return segs


def key(p):
    return (round(p[0], 6) + 0.0, round(p[1], 6) + 0.0)


def build_graph(segs):
    adj, edges = {}, set()
    for a, b in segs:
        ka, kb = key(a), key(b)
        if ka == kb:
            continue
        edges.add(frozenset((ka, kb)))
        adj.setdefault(ka, set()).add(kb)
        adj.setdefault(kb, set()).add(ka)
    return adj, edges


def find_cycles(adj, maxlen=12):
    nodes = sorted(adj)
    rank = {v: i for i, v in enumerate(nodes)}
    found = {}

    def dfs(start, v, path, onpath):
        for w in adj[v]:
            if w == start and len(path) >= 3:
                canon = frozenset(
                    frozenset((path[i], path[(i + 1) % len(path)])) for i in range(len(path))
                )
                found.setdefault(canon, list(path))
            elif w not in onpath and rank[w] > rank[start] and len(path) < maxlen:
                onpath.add(w)
                path.append(w)
                dfs(start, w, path, onpath)
                path.pop()
                onpath.discard(w)

    for s in nodes:
        dfs(s, s, [s], {s})
    return list(found.values())


def reduce_corners(pts):
    pts = list(pts)
    while len(pts) > 3:
        n = len(pts)
        removed = False
        for i in range(n):
            a, b, c = pts[i - 1], pts[i], pts[(i + 1) % n]
            u, v = sub(b, a), sub(c, b)
            if norm(u) > 0 and norm(v) > 0 and sin_between(u, v) < TOL and dot(u, v) > 0:
                del pts[i]
                removed = True
                break
        if not removed:
            break
    return pts


def area2(pts):
    s = 0.0
    for i in range(len(pts)):
        x1, y1 = pts[i]
        x2, y2 = pts[(i + 1) % len(pts)]
        s += x1 * y2 - x2 * y1
    return s


def proper_cross(p1, p2, p3, p4):
    d1 = cross(sub(p2, p1), sub(p3, p1))
    d2 = cross(sub(p2, p1), sub(p4, p1))
    d3 = cross(sub(p4, p3), sub(p1, p3))
    d4 = cross(sub(p4, p3), sub(p2, p3))
    return d1 * d2 < 0 and d3 * d4 < 0


def is_simple(pts):
    k = len(pts)
    for i in range(k):
        for j in range(i + 1, k):
            if j == i + 1 or (i == 0 and j == k - 1):
                continue
            if proper_cross(pts[i], pts[(i + 1) % k], pts[j], pts[(j + 1) % k]):
                return False
    return True


def is_convex(pts):
    k = len(pts)
    E = [sub(pts[(i + 1) % k], pts[i]) for i in range(k)]
    s = [cross(E[i], E[(i + 1) % k]) for i in range(k)]
    return all(x > 0 for x in s) or all(x < 0 for x in s)


def covered(a, b, edges):
    d = sub(b, a)
    L = norm(d)
    ivs = []
    for e in edges:
        p, q = tuple(e)
        if abs(cross(d, sub(p, a))) / L > TOL * 10 or abs(cross(d, sub(q, a))) / L > TOL * 10:
            continue
        tp = dot(sub(p, a), d) / (L * L)
        tq = dot(sub(q, a), d) / (L * L)
        lo, hi = max(0.0, min(tp, tq)), min(1.0, max(tp, tq))
        if hi > lo:
            ivs.append((lo, hi))
    ivs.sort()
    cur = 0.0
    for lo, hi in ivs:
        if lo > cur + 1e-6:
            return False
        cur = max(cur, hi)
    return cur >= 1 - 1e-6


def has_diagonal(pts, edges):
    k = len(pts)
    for i in range(k):
        for j in range(i + 2, k):
            if i == 0 and j == k - 1:
                continue
            if covered(pts[i], pts[j], edges):
                return True
    return False


def classify(pts, diag):
    k = len(pts)
    E = [sub(pts[(i + 1) % k], pts[i]) for i in range(k)]
    if k == 3:
        right = any(
            abs(cos_between(sub(pts[(i - 1) % 3], pts[i]), sub(pts[(i + 1) % 3], pts[i]))) < TOL
            for i in range(3)
        )
        return 4 if right else 3
    if diag:
        return None
    if k == 4:
        par_a = sin_between(E[0], E[2]) < TOL
        par_b = sin_between(E[1], E[3]) < TOL
        if par_a and par_b:
            rect = all(abs(cos_between(E[i], E[(i + 1) % 4])) < TOL for i in range(4))
            if rect:
                s0, s1 = norm(E[0]), norm(E[1])
                square = abs(s0 - s1) <= LEN_TOL * max(s0, s1)
                return 2 if square else 1
            return 5
        if par_a != par_b:
            return 6
        return None
    if k == 5:
        if not is_convex(pts):
            return 8 if is_simple(pts) else None
        lens = [norm(e) for e in E]
        equal_sides = max(lens) - min(lens) <= LEN_TOL * max(lens)
        turns = [cos_between(E[i], E[(i + 1) % 5]) for i in range(5)]
        equal_angles = max(turns) - min(turns) < TOL
        return 9 if (equal_sides and equal_angles) else 7
    if k == 6:
        if not is_convex(pts):
            return None
        lens = [norm(e) for e in E]
        equal_sides = max(lens) - min(lens) <= LEN_TOL * max(lens)
        turns = [cos_between(E[i], E[(i + 1) % 6]) for i in range(6)]
        equal_angles = max(turns) - min(turns) < TOL
        return 10 if (equal_sides and equal_angles) else None
    return None


def main():
    segs = parse_segments(PATH)
    adj, edges = build_graph(segs)
    cycles = find_cycles(adj, maxlen=12)

    shapes = []
    for cyc in cycles:
        pts = reduce_corners(cyc)
        if not (3 <= len(pts) <= 6):
            continue
        if abs(area2(pts)) < 1e-9:
            continue
        if not is_simple(pts):
            continue
        diag = has_diagonal(pts, edges)
        cat = classify(pts, diag)
        shapes.append({"corners": len(pts), "diagonals_drawn": diag, "category": cat})

    matched = {s["category"] for s in shapes if s["category"] is not None}
    options = [L for L, s in OPTIONS.items() if s == matched]

    if len(options) == 1:
        final = "(" + options[0] + ")"
    else:
        final = "UNSUPPORTED"

    out = {
        "final_answer": final,
        "evidence": {
            "segments": len(segs),
            "nodes": len(adj),
            "cycles_found": len(cycles),
            "closed_shapes": shapes,
            "matched_categories": sorted(matched),
            "matching_options": options,
        },
    }
    print(json.dumps(out, separators=(",", ":")))


main()
