import itertools
import json
from fractions import Fraction

# Finite-model enumeration over 3 individuals: Liu, p1, p2.
# Predicates per individual:
#   M = member of Save the Earth
#   V = qualified Shanghai World Expo volunteer
#   N = volunteer of "Expo news" (a separate predicate, unconstrained by premises)
people = ["Liu", "p1", "p2"]
others = [p for p in people if p != "Liu"]
cells = list(itertools.product([0, 1], repeat=3))  # (M, V, N)

def premises_hold(m):
    # P1: Xiao Liu is a member of Save the Earth.
    if m["Liu"][0] != 1:
        return False
    # P2: Xiao Liu cannot volunteer, so he lacks the qualification.
    if m["Liu"][1] != 0:
        return False
    # P3: other members have obtained the qualification (at least one such member).
    if not any(m[p][0] == 1 and m[p][1] == 1 for p in others):
        return False
    return True

def opt_A(m):
    # Xiao Liu is a member but not a qualified volunteer.
    return m["Liu"][0] == 1 and m["Liu"][1] == 0

def opt_B(m):
    # Every qualified volunteer is a member.
    return all((not (m[p][1] == 1)) or m[p][0] == 1 for p in people)

def opt_C(m):
    # Any news volunteer who is a member is not Xiao Liu.
    return all(not (m[p][2] == 1 and m[p][0] == 1) or p != "Liu" for p in people)

def opt_D(m):
    # Any member who is not a qualified volunteer must be Xiao Liu.
    return all(not (m[p][0] == 1 and m[p][1] == 0) or p == "Liu" for p in people)

options = {"A": opt_A, "B": opt_B, "C": opt_C, "D": opt_D}

models_total = 0
models_valid = 0
entailed = {k: True for k in options}
counterexample = {}

for combo in itertools.product(cells, repeat=len(people)):
    m = dict(zip(people, combo))
    models_total += 1
    if not premises_hold(m):
        continue
    models_valid += 1
    for k, f in options.items():
        if entailed[k] and not f(m):
            entailed[k] = False
            counterexample[k] = {p: list(m[p]) for p in people}

entailed_letters = [k for k in sorted(options) if entailed[k]]

if len(entailed_letters) == 1:
    final_answer = entailed_letters[0]
else:
    final_answer = "UNSUPPORTED"

result = {
    "final_answer": final_answer,
    "evidence": {
        "models_total": models_total,
        "models_satisfying_premises": models_valid,
        "entailed_options": entailed_letters,
        "counterexamples_for_rejected": {k: counterexample[k] for k in counterexample},
        "fraction_check": str(Fraction(models_valid, models_total)),
    },
}

print(json.dumps(result, separators=(",", ":")))
