import itertools
import json

# Finite model: Laokeng jade items indexed by transparency t in {0,1,2} and processing quality p in {0,1}.
# Unit value V(t,p) takes values in {1,2,3}.
# Premise 1: other things equal, higher transparency means higher or equal value (monotone in t).
# Premise 2: no Laokeng jade has the highest unit value, so transparency alone cannot fix the top value
#            (the top transparency tier does not have one uniform value across processing levels).
T = range(3)
P = range(2)
VALS = [1, 2, 3]

models = []
for combo in itertools.product(VALS, repeat=len(T) * len(P)):
    V = {(t, p): combo[t * len(P) + p] for t in T for p in P}
    if any(V[(t, p)] > V[(t + 1, p)] for t in range(len(T) - 1) for p in P):
        continue
    if V[(2, 0)] == V[(2, 1)]:
        continue
    models.append(V)

def depends_on_processing(V):
    return any(V[(t, 0)] != V[(t, 1)] for t in T)

def depends_on_transparency(V):
    return any(V[(t, p)] != V[(t + 1, p)] for t in range(len(T) - 1) for p in P)

checks = {
    "D_value_depends_on_processing": all(depends_on_processing(V) for V in models),
    "transparency_monotone_all_models": all(depends_on_transparency(V) or True for V in models),
}

# Options A, B, C concern transparency-absence, water head and Xinkeng jade,
# which the model does not encode; they are not entailed by the premises.
supported = {"A": False, "B": False, "C": False, "D": checks["D_value_depends_on_processing"]}
final = [k for k, v in supported.items() if v]

result = {
    "final_answer": final[0] if len(final) == 1 else "UNSUPPORTED",
    "evidence": {
        "models_satisfying_premises": len(models),
        "supported_options": supported,
