import re, math, json

PATH = ("M 12.75,29.11117 L 12.75,17.61117 M 4.08,29.11117 L 0.0,29.11117 M 9.95929,23.36117 L 5.17883,20.60117 "
        "M 12.75,10.61117 L 18.81218,14.11117 M 12.75,29.11117 L 4.08,29.11117 M 16.20544,15.61617 L 12.75,17.61117 "
        "M 0.0,17.61117 L 12.75,17.61117 M 0.0,29.11117 L 9.95929,23.36117 M 12.75,17.61117 L 12.75,29.11117 "
        "M 12.75,17.61117 L 32.25,17.61117 L 32.25,16.00117 M 32.25,29.11117 L 12.75,29.11117 "
        "M 18.81218,14.11117 L 16.20544,15.61617 M 5.17883,20.60117 L 0.0,17.61117 M 0.0,0.0 L 0.0,17.61117 "
        "M 32.25,16.00117 L 32.25,10.61117 L 27.765,10.61117 L 12.75,10.61117 M 32.25,17.61117 L 32.25,29.11117 "
        "M 12.75,17.61117 L 12.75,0.0")

EPS = 1e-3

OPTIONS = {
    "A": {1, 8, 10}, "B": {8, 2}, "C": {8, 2, 6}, "D": {8, 3, 6}, "E": {8},
    "F": {1, 8}, "H": {1, 5}, "I": {1, 8, 2}, "J": {8, 10}, "K": {1},
    "L": {1, 6, 10}, "M": {8, 3}, "N": {8, 7}, "O": {1, 4, 7, 10}, "P": {6, 10},
}

def dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])

def parse(d):
    segs, cur = [], None
    for cmd, x, y in re.findall(r'([ML])\s*([-+]?\d*\.?\d+)\s*,\s*([-+]?\d*\.?\d+)', d):
        p = (float(x), float(y))
        if cmd == 'M':
            cur = p
        else:
            segs.append((cur, p))
            cur = p
    return segs

def on_seg(p, a, b):
    L = dist(a, b)
    t = ((p[0] - a[0]) * (b[0] - a[0]) + (p[1] - a[1]) * (b[1] - a[1])) / (L * L)
    if not (EPS < t < 1 - EPS):
        return False
    cross = abs((b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])) / L
    return cross < EPS

def pt_seg_dist(p, a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    L2 = dx * dx + dy * dy
    t = max(0.0, min(1.0, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L2))
    return math.hypot(p[0] - (a[0] + t * dx), p[1] - (a[1] + t * dy))

# 1. vertices (merge coincident endpoints)
verts = []
def vid(p):
    for i, v in enumerate(verts):
        if dist(v, p) < EPS:
            return i
    verts.append(p)
    return len(verts) - 1

raw = [(vid(a), vid(b)) for a, b in parse(PATH)]

# 2. split segments at T-junctions, collect unique undirected edges
edges = set()
for i, j in raw:
    if i == j:
        continue
    a, b = verts[i], verts[j]
    pts = [i, j] + [k for k, p in enumerate(verts) if k not in (i, j) and on_seg(p, a, b)]
    pts.sort(key=lambda k: dist(a, verts[k]))
    for u, v in zip(pts, pts[1:]):
        edges.add((min(u, v), max(u, v)))

def covered(p, q, samples=40):
    """True if the whole segment p-q lies on drawn edges (i.e. the line is drawn)."""
    for k in range(1, samples):
        t = k / samples
        x = p[0] + (q[0] - p[0]) * t
        y = p[1] + (q[1] - p[1]) * t
        if not any(pt_seg_dist((x, y), verts[u], verts[v]) < 1e-3 for u, v in edges):
            return False
    return True

# 3. planar face tracing (half-edges, next = previous CCW neighbour)
def trace():
    adj = {i: [] for i in range(len(verts))}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    for u in adj:
        adj[u].sort(key=lambda w: math.atan2(verts[w][1] - verts[u][1], verts[w][0] - verts[u][0]))
    seen, faces = set(), []
    for u in adj:
        for v in adj[u]:
            if (u, v) in seen:
                continue
            cyc, a, b = [], u, v
            while (a, b) not in seen:
                seen.add((a, b))
                cyc.append(verts[a])
                nb = adj[b]
                c = nb[(nb.index(a) - 1) % len(nb)]
                a, b = b, c
            faces.append(cyc)
    return faces

def signed_area(poly):
    s = 0.0
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        s += x1 * y2 - x2 * y1
    return s / 2

def corners(poly):
    p = list(poly)
    while len(p) > 3:
        removed = False
        for i in range(len(p)):
            a, b, c = p[i - 1], p[i], p[(i + 1) % len(p)]
            u = (b[0] - a[0], b[1] - a[1])
            w = (c[0] - b[0], c[1] - b[1])
            lu, lw = math.hypot(*u), math.hypot(*w)
            if lu < EPS or lw < EPS or (abs(u[0] * w[1] - u[1] * w[0]) / (lu * lw) < 1e-4
                                        and u[0] * w[0] + u[1] * w[1] > 0):
                del p[i]
                removed = True
                break
        if not removed:
            break
    return p

def turns(c):
    n = len(c)
    out = []
    for i in range(n):
        a, b, d = c[i - 1], c[i], c[(i + 1) % n]
        u = (b[0] - a[0], b[1] - a[1])
        w = (d[0] - b[0], d[1] - b[1])
        out.append(math.degrees(math.atan2(u[0] * w[1] - u[1] * w[0], u[0] * w[0] + u[1] * w[1])))
    return out

def shapes_of(c):
    n = len(c)
    tr = turns(c)                      # positive = left turn (CCW face)
    ang = [180.0 - t for t in tr]      # interior angles
    sides = [dist(c[i], c[(i + 1) % n]) for i in range(n)]

    def sv(i):
        return (c[(i + 1) % n][0] - c[i][0], c[(i + 1) % n][1] - c[i][1])

    def par(i, j):
        u, w = sv(i), sv(j)
        return abs(u[0] * w[1] - u[1] * w[0]) / (math.hypot(*u) * math.hypot(*w)) < 1e-3

    npar = sum(par(i, j) for i in range(n) for j in range(i + 1, n))
    convex = all(t > 0 for t in tr)
    right = any(abs(a - 90) < 0.5 for a in ang)
    rect = n == 4 and all(abs(a - 90) < 0.5 for a in ang)
    eq_sides = max(sides) - min(sides) < 1e-3
    square = rect and eq_sides
    regular = convex and eq_sides and (max(ang) - min(ang) < 0.5)
    para = n == 4 and par(0, 2) and par(1, 3)
    nodiag = not any(covered(c[i], c[j])
                     for i in range(n) for j in range(i + 2, n)
                     if not (i == 0 and j == n - 1))

    s = set()
    if n == 4 and rect and not square and nodiag: s.add(1)
    if n == 4 and square and nodiag: s.add(2)
    if n == 3 and not right and nodiag: s.add(3)
    if n == 3 and right: s.add(4)
    if n == 4 and para and not rect and nodiag: s.add(5)
    if n == 4 and npar == 1 and nodiag: s.add(6)
    if n == 5 and convex and not regular and nodiag: s.add(7)
    if n == 5 and not convex and nodiag: s.add(8)
    if n == 5 and regular and nodiag: s.add(9)
    if n == 6 and regular and nodiag: s.add(10)
    return s

# 4. evaluate bounded faces (positive signed area; outer face is negative)
viewable = set()
faces_info = []
for poly in trace():
    if signed_area(poly) <= EPS:
        continue
    c = corners(poly)
    sh = shapes_of(c)
    viewable |= sh
    faces_info.append({"corners": len(c), "convex": all(t > 0 for t in turns(c)),
                       "shapes": sorted(sh)})

# 5. map computed shape set to an option letter
ans = "G"  # none of the above, unless a listed option matches exactly
for letter, s in OPTIONS.items():
    if s == viewable:
        ans = letter

print(json.dumps({"final_answer": ans,
                  "evidence": {"viewable_shape_ids": sorted(viewable),
                               "bounded_faces": faces_info}},
                 separators=(",", ":")))
