def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def cross(u, v):
    return u[0] * v[1] - u[1] * v[0]


def dot(u, v):
    return u[0] * v[0] + u[1] * v[1]


def on_seg(p, a, b):
    if cross(sub(b, a), sub(p, a)) != 0:
        return False
    return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
            min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))


def inter(a, b, c, d):
    r = sub(b, a)
    s = sub(d, c)
    den = cross(r, s)
    if den == 0:
        return None
    qp = sub(c, a)
    t = cross(qp, s) / den
    u = cross(qp, r) / den
    if 0 <= t <= 1 and 0 <= u <= 1:
        return (a[0] + t * r[0], a[1] + t * r[1])
    return None


def corners(cyc):
    n = len(cyc)
    out = []
    for i in range(n):
        p = cyc[i - 1]
        c = cyc[i]
        q = cyc[(i + 1) % n]
        if cross(sub(c, p), sub(q, c)) != 0:
            out.append(c)
    return out


def regular(C):
    n = len(C)
    es = [sub(C[(i + 1) % n], C[i]) for i in range(n)]
    L = [math.hypot(float(e[0]), float(e[1])) for e in es]
    if max(L) - min(L) > 1e-3 * max(L):
        return False
    ang = []
    for i in range(n):
        a = es[i - 1]
        b = es[i]
        t = math.atan2(float(cross(a, b)), float(dot(a, b)))
        ang.append(math.pi - t)
    return max(ang) - min(ang) < 1e-3


def classify(C):
    n = len(C)
    es = [sub(C[(i + 1) % n], C[i]) for i in range(n)]
    turns = [cross(es[i - 1], es[i]) for i in range(n)]
    dots = [dot(es[i - 1], es[i]) for i in range(n)]
    convex = all(t > 0 for t in turns)
    tags = set()
    if n == 3:
        tags.add(4 if any(d == 0 for d in dots) else 3)
    elif n == 4:
        par = [cross(es[0], es[2]) == 0, cross(es[1], es[3]) == 0]
        rect = all(d == 0 for d in dots)
        if rect:
            tags.add(2 if dot(es[0], es[0]) == dot(es[1], es[1]) else 1)
        elif sum(par) == 2:
            tags.add(5)
        elif sum(par) == 1:
            tags.add(6)
    elif n == 5:
        if not convex:
            tags.add(8)
        elif regular(C):
            tags.add(9)
        else:
            tags.add(7)
    elif n == 6:
        if convex and regular(C):
