    for e in edges:
        p, q = tuple(e)
        adj.setdefault(p, []).append(q)
        adj.setdefault(q, []).append(p)
    for v in adj:
        adj[v].sort(key=lambda w: math.atan2(float(w[1] - v[1]), float(w[0] - v[0])))

    start = next(iter(adj))
    seen = {start}
    stack = [start]
    while stack:
        x = stack.pop()
        for y in adj[x]:
            if y not in seen:
                seen.add(y)
                stack.append(y)
    connected = len(seen) == len(adj)

    visited = set()
    faces = []
    for u in adj:
        for v in adj[u]:
            if (u, v) in visited:
                continue
            cyc = []
            a, b = u, v
            while (a, b) not in visited:
                visited.add((a, b))
                cyc.append(a)
                nb = adj[b]
                k = nb.index(a)
                a, b = b, nb[(k - 1) % len(nb)]
            faces.append(cyc)

    found = set()
    report = []
    for cyc in faces:
        area2 = sum(cross(cyc[i], cyc[(i + 1) % len(cyc)]) for i in range(len(cyc)))
        if area2 <= 0:
            continue
        C = corners(cyc)
        tags = classify(C)
        report.append({"corners": len(C), "tags": sorted(tags)})
        found |= tags

    matches = [k for k, v in OPTS.items() if v == found]
    final = "(%s)" % matches[0] if len(matches) == 1 else "UNSUPPORTED"
    print(json.dumps({
        "final_answer": final,
        "evidence": {
            "connected": connected,
            "visible_types": sorted(found),
            "bounded_faces": report,
        },
    }))


main()
