import json
import math
from fractions import Fraction as F

# Irrational test point x = sqrt(2), enclosed in exact rational bounds [L, U].
SCALE = 10**40
L = F(math.isqrt(2 * SCALE * SCALE), SCALE)
U = L + F(1, SCALE)

def certainly_outside(q, t):
    """True iff |q - x| >= t for every x in [L, U], so the open interval
    (q - t, q + t) misses [L, U] entirely."""
    if q < L:
        lo = L - q
    elif q > U:
        lo = q - U
    else:
        return False
    return lo >= t

def rationals(limit):
    """Enumerate all reduced rationals by height s = |p| + q (q >= 1)."""
    out = [F(0)]
    s = 2
    while len(out) < limit:
        for a in range(0, s):
            q = s - a
            if q < 1 or math.gcd(a, q) != 1:
                continue
            out.append(F(a, q))
            if a != 0:
                out.append(F(-a, q))
        s += 1
    return out[:limit]

def build(N, M):
    R = rationals(M)
    placed = [False] * M
    assign = {}
    for n in range(1, N + 1):
        t = F(1, n)
        chosen = None
        for i in range(M):
            if not placed[i] and certainly_outside(R[i], t):
                chosen = i
                break
        if chosen is None:
            return None
        placed[chosen] = True
        assign[n] = chosen
    return R, assign

def verify(R, assign):
    for n, i in assign.items():
        if not certainly_outside(R[i], F(1, n)):
            return False
    return len(set(assign.values())) == len(assign)

N, M = 200, 1500
result = build(N, M)

if result is None:
    print(json.dumps({"final_answer": "UNSUPPORTED",
                      "evidence": {"reason": "no eligible rational found in prefix",
                                   "N": N, "M": M}}))
else:
    R, assign = result
    ok = verify(R, assign)
    if ok:
        sample = [f"r_{n}={R[assign[n]].numerator}/{R[assign[n]].denominator}"
                  for n in range(1, 11)]
        print(json.dumps({
            "final_answer": "Yes",
            "evidence": {
                "uncovered_point_interval": [str(L), str(U)],
                "indices_checked": N,
                "rationals_in_prefix": M,
                "all_distances_ge_1_over_n": True,
                "sample_assignments": sample
            }
        }))
    else:
        print(json.dumps({"final_answer": "UNSUPPORTED",
                          "evidence": {"reason": "verification failed",
                                       "N": N, "M": M}}))
