from fractions import Fraction as F

# Claimed final answer: (-inf, -1/3) U (1, inf)
def claimed(x):
    return x < F(-1, 3) or x > 1

def premise_holds(a, b, c, xs):
    # Premise: solution set of a x^2 + b x + c <= 0 is exactly {x <= -1 or x >= 3}
    for x in xs:
        lhs = a * x * x + b * x + c <= 0
        target = (x <= -1) or (x >= 3)
        if lhs != target:
            return False
    return True

# Test points: rationals in [-10, 10] with step 1/4, including -1, 3, -1/3, 1
xs = [F(n, 4) for n in range(-40, 41)]

# Search integer triples (a, b, c) with a != 0
valid = []
for a in range(-6, 7):
    if a == 0:
        continue
    for b in range(-6, 7):
        for c in range(-6, 7):
            if premise_holds(a, b, c, xs):
                valid.append((a, b, c))

print("Premise-satisfying integer triples found:", len(valid))
print("Triples:", valid)

counterexample = None
for (a, b, c) in valid:
    for x in xs:
        actual = c * x * x - b * x + a < 0
        if actual != claimed(x):
            counterexample = (a, b, c, x)
            break
    if counterexample:
        break

if counterexample is None:
    print("No mismatch found on grid for any premise-satisfying triple.")
    print("CHECK UNKNOWN: no counterexample in grid of x in [-10,10] step 1/4, a,b,c in [-6,6]")
else:
    a, b, c, x = counterexample
    lhs_premise = a * x * x + b * x + c
    lhs_target = c * x * x - b * x + a
    print("Counterexample found:")
    print(f"  a={a}, b={b}, c={c}, x={x}")
    print(f"  premise side  a*x^2+b*x+c = {lhs_premise}  (<= 0 : {lhs_premise <= 0})")
    print(f"  target side   c*x^2-b*x+a = {lhs_target}  (< 0 : {lhs_target < 0})")
    print(f"  x in claimed set (-inf,-1/3)U(1,inf): {claimed(x)}")
    print("Analysis: premise {x<=-1 or x>=3} forces a<0 (a(x+1)(x-3)<=0 with a<0),")
    print("so with a=-1,b=2,c=3 the target inequality is 3x^2-2x-1<0, i.e. (3x+1)(x-1)<0,")
    print("with solution set (-1/3, 1), not the claimed set.")
    print("CHECK FAIL")
